script:
class Component extends DCLogic {
  constructor(props) { super(props); this.state = { q: '', cat: 'all', open: {}, m: '', kind: '', tText: '', tErr: false, tFile: false, tDone: false, tickets: [], fbText: '', fbErr: false }; }

  _y(e) { try { const m = document.querySelector('main.kab__main'); return Math.round(e.currentTarget.getBoundingClientRect().top - m.getBoundingClientRect().top); } catch (x) { return 120; } }
  say(msg, e) { const y = this._y(e); this.setState({ toast: msg, toastY: Math.max(8, y + ((e && e.currentTarget && e.currentTarget.offsetHeight) || 40) + 8) }); clearTimeout(this._tt); this._tt = setTimeout(() => this.setState({ toast: '' }), 3800); }
  openM(name, e, extra) { const y = this._y(e); this.setState(Object.assign({ m: name, mTop: Math.max(16, y - 40) }, extra || {})); }
  closeM() { this.setState({ m: '' }); }
  baseVals() {
    const S = this.state;
    return { toastOn: !!S.toast, toast: S.toast || '', toastStyle: 'top:' + (S.toastY || 80) + 'px;width:max-content;max-width:min(420px,calc(100% - 32px))', mOn: !!S.m, ovlStyle: 'padding-top:' + (S.mTop || 24) + 'px',
      closeOvl: (e) => { if (e.target === e.currentTarget) this.closeM(); }, closeBtn: () => this.closeM(),
      helpOpen: (e) => this.openM('help', e), m_help: S.m === 'help' };
  }

  renderVals() {
    const S = this.state;
    const ALL = [
      { c: 'ag', q: 'Как стать агентом Housebook?', a: 'Зарегистрируйтесь в кабинете, заполните профиль и подпишите договор. После этого можно передавать клиентов, собирать подборки и приглашать других агентов.' },
      { c: 'ag', q: 'Что даёт платформа агенту?', a: 'Передача клиентов и отслеживание заявок в реальном времени, персональные подборки, каталог проектов с ценами, личная ссылка для клиентов, генератор контента и реферальная сеть.' },
      { c: 'ag', q: 'Как передать клиента и когда фиксируется моя доля?', a: 'Передайте контакт клиента в разделе «Клиенты». Доля зависит от готовности клиента, а по конкретной заявке фиксируется при её закрытии и видна в самой заявке.' },
      { c: 'ag', q: 'Сколько я получу с заявки?', a: 'Платформа удерживает 20%, остальное делится по готовности клиента: Ваша доля 40%, 35% или 30%. Точные условия по странам есть в гиде по платформе.' },
      { c: 'ag', q: 'Как работает сеть агента?', a: 'Приглашайте агентов и получайте долю сетевого пула с их заявок: 5% комиссии из доли платформы, до пяти уровней. Подробности в разделе «Команда».' },
      { c: 'co', q: 'Как связаться с поддержкой Housebook?', a: 'Напишите в чат в кабинете или в WhatsApp. Мы читаем каждое обращение и отвечаем.' }];
    const qq = S.q.trim().toLowerCase();
    const hit = ALL.filter((f) => (S.cat === 'all' || f.c === S.cat) && (!qq || (f.q + ' ' + f.a).toLowerCase().indexOf(qq) >= 0));
    const faqs = hit.map((f) => ({ q: f.q, a: f.a, open: !!S.open[f.q], pick: () => this.setState({ open: Object.assign({}, S.open, { [f.q]: !S.open[f.q] }) }) }));
    const CATS = [['all', 'Все', 6], ['ag', 'Для агентов', 5], ['co', 'Связь', 1]];
    const cats = CATS.map(([k, t, n]) => ({ t, n, on: S.cat === k, pick: () => this.setState({ cat: k }) }));
    const KINDS = ['Не могу работать', 'Работает не так', 'Непонятно', 'Есть предложение', 'Ошибка в данных'];
    const tKinds = KINDS.map((t) => ({ t, on: S.kind === t, pick: () => this.setState({ kind: S.kind === t ? '' : t }) }));
    const tNum = '№' + (412 + S.tickets.length);
    return Object.assign(this.baseVals(), { q: S.q, setQ: (e) => this.setState({ q: e.target.value }), cats, faqs, noFaq: faqs.length === 0, sayWa: (e) => this.say('В кабинете откроется WhatsApp', e), sayGuide: (e) => this.say('В кабинете откроется гид', e),
      tickets: S.tickets, noTickets: S.tickets.length === 0, m_ticket: S.m === 'ticket', tForm: !S.tDone, tDone: S.tDone, tNum, tKinds, tText: S.tText, tSet: (e) => this.setState({ tText: e.target.value, tErr: false }),
      tErr: S.tErr && S.tText.trim().length < 5 ? 'is-err' : '', tErr_e: S.tErr && S.tText.trim().length < 5 ? 'Опишите хотя бы в двух словах, что случилось' : '', tHasFile: S.tFile, tAttach: (e) => { this.setState({ tFile: true }); this.say('Файл прикреплён', e); },
      ticketOpen: (e) => this.openM('ticket', e, { tDone: false, tErr: false, tText: '', tFile: false, kind: '' }),
      tSend: (e) => { if (e && e.preventDefault) e.preventDefault(); if (S.tText.trim().length < 5) { this.setState({ tErr: true }); return; } this.setState({ tDone: true, tickets: S.tickets.concat([{ n: 'Обращение ' + tNum, s: (S.kind ? S.kind + '. ' : '') + S.tText.trim().slice(0, 60) }]) }); },
      fbText: S.fbText, fbSet: (e) => this.setState({ fbText: e.target.value, fbErr: false }), fbErr: S.fbErr && !S.fbText.trim() ? 'is-err' : '', fbErr_e: S.fbErr && !S.fbText.trim() ? 'Напишите пару слов' : '',
      fbSend: (e) => { if (e && e.preventDefault) e.preventDefault(); if (!S.fbText.trim()) { this.setState({ fbErr: true }); return; } this.setState({ fbText: '' }); this.say('Спасибо, мы это прочтём', e); } });
  }
}
